// Calculate quality score based on document characteristics
const items = $input.all();

console.log('=== Calculate Quality Score ===');
console.log(`Received ${items.length} items (chunks)`);

if (items.length === 0) {
  throw new Error('No items received');
}

const firstItem = items[0].json;
console.log('First item keys:', Object.keys(firstItem));
console.log('Document ID:', firstItem.document_id);

// Get document_id from chunks (all chunks have same document_id)
const documentId = firstItem.document_id;

// Calculate metrics
const chunkCount = items.length;
const avgChunkSize = items.reduce((sum, item) => sum + (item.json.chunk_size || 0), 0) / chunkCount;
const hasFilename = !!firstItem.filename;
const filenameQuality = hasFilename && firstItem.filename.length > 5 ? 0.2 : 0;

console.log(`Chunk count: ${chunkCount}`);
console.log(`Average chunk size: ${avgChunkSize}`);

// Quality score components:
// - Chunk count (optimal 3-20 chunks): 0-0.3
// - Average chunk size (optimal 300-600 chars): 0-0.3
// - Has filename: 0.2
// - Has metadata: 0.2

let chunkScore = 0.3;
if (chunkCount < 2) chunkScore = 0.1;
else if (chunkCount > 50) chunkScore = 0.15;

let sizeScore = 0.3;
if (avgChunkSize < 100) sizeScore = 0.1;
else if (avgChunkSize > 1000) sizeScore = 0.15;

const qualityScore = chunkScore + sizeScore + filenameQuality + 0.2;

console.log(`Quality score: ${qualityScore}`);
console.log(`Auto-approve: ${qualityScore >= 0.7}`);

return {
  json: {
    document_id: documentId,
    quality_score: parseFloat(Math.min(qualityScore, 1.0).toFixed(2)),
    chunk_count: chunkCount,
    avg_token_count: Math.round(avgChunkSize / 4), // Rough estimate: 4 chars per token
    auto_approve: qualityScore >= 0.7,
    filename: firstItem.filename
  }
};

